  'settings.sfTeamDesc': { 'zh-Hans': '1 对 1 定制 · 24 小时交付原型初稿', en: 'One-to-one and a first prototype within 24 hours', ko: '1:1 맞춤 · 24시간 내 프로토타입 초안 제공', es: 'Atención uno a uno · primer prototipo en 24 horas', vi: 'Tư vấn 1-1 · bản mẫu đầu tiên trong 24 giờ' },
  'settings.sfPoint1Bold': { 'zh-Hans': '并非通用模板机械生成', en: 'Not a generic template', ko: '범용 템플릿의 기계적 생성이 아닙니다', es: 'No es una plantilla genérica', vi: 'Không phải mẫu chung tạo tự động' },
  'settings.sfPoint1Body': { 'zh-Hans': '：由资深 Web 设计师根据您的门店实际空间照片、技师专长与品牌调性量身绘制。', en: ': a senior web designer draws the layout around your actual space photos, therapist specialities and brand tone.', ko: '：경력 웹 디자이너가 실제 매장 사진, 관리사 전문 분야, 브랜드 톤에 맞춰 직접 설계합니다.', es: ': un diseñador web sénior lo compone a partir de tus fotos reales, las especialidades del equipo y tu tono de marca.', vi: '：nhà thiết kế web giàu kinh nghiệm dựng riêng dựa trên ảnh không gian thật, thế mạnh KTV và tông thương hiệu.' },
  'settings.sfPoint2Bold': { 'zh-Hans': '开箱即用在线预约闭环', en: 'Booking loop that works on day one', ko: '즉시 사용 가능한 온라인 예약 순환', es: 'Reservas listas desde el primer día', vi: 'Vòng đặt lịch dùng được ngay' },
  'settings.sfPoint2Body': { 'zh-Hans': '：直接与前台排班日历打通，客人下单后无需人工再抄写一遍。', en: ': wired straight into the front-desk calendar, so no one has to re-enter a booking by hand.', ko: '：프런트 배치 캘린더와 직접 연동되어 고객 예약을 수기로 다시 옮길 필요가 없습니다.', es: ': conectado directamente al calendario de recepción, sin volver a anotar nada a mano.', vi: '：kết nối thẳng với lịch của quầy lễ tân, không phải chép lại lịch hẹn bằng tay.' },
  'settings.sfPoint3Bold': { 'zh-Hans': '极速 Google SEO 与 Maps 优化', en: 'Google SEO and Maps optimisation', ko: 'Google SEO 및 지도 최적화', es: 'Optimización para Google SEO y Maps', vi: 'Tối ưu Google SEO và Maps' },
  'settings.sfPoint3Body': { 'zh-Hans': '：包含结构化数据与移动端加速，助力本地自然进客。', en: ': structured data and mobile acceleration included, to drive local organic traffic.', ko: '：구조화 데이터와 모바일 가속을 포함하여 지역 검색 유입을 높입니다.', es: ': incluye datos estructurados y aceleración móvil para atraer tráfico local orgánico.', vi: '：bao gồm dữ liệu cấu trúc và tăng tốc di động, giúp thu hút khách địa phương.' },
  'settings.sfDomainTitle': { 'zh-Hans': '支持独立顶级域名绑定:', en: 'Custom domain supported:', ko: '독립 도메인 연결 지원:', es: 'Dominio propio compatible:', vi: 'Hỗ trợ gắn tên miền riêng:' },
  'settings.sfDomainBody': { 'zh-Hans': '可绑定您自己的专属域名 (如 www.yourspa.com)，免费提供全球 CDN 加速与 SSL 自动续期。', en: 'Bind your own domain (e.g. www.yourspa.com) with free global CDN acceleration and automatic SSL renewal.', ko: '고유 도메인(예: www.yourspa.com)을 연결할 수 있으며, 전 세계 CDN 가속과 SSL 자동 갱신을 무료로 제공합니다.', es: 'Vincula tu propio dominio (p. ej. www.yourspa.com) con CDN global gratuita y renovación automática del SSL.', vi: 'Có thể gắn tên miền riêng (ví dụ www.yourspa.com), kèm CDN toàn cầu và tự động gia hạn SSL miễn phí.' },
