  'settings.sfFeedbackConfirmTitle': { 'zh-Hans': '确认向专属设计师提交修改批注？', en: 'Send these revision notes to your designer?', ko: '전담 디자이너에게 수정 의견을 보내시겠습니까?', es: '¿Enviar estos comentarios al diseñador?', vi: 'Gửi ghi chú chỉnh sửa cho nhà thiết kế?' },
