  'settings.stContactDesc': { 'zh-Hans': '顾客咨询与预约确认邮件将使用该信息', en: 'Used for customer enquiries and booking confirmation emails', ko: '고객 문의와 예약 확인 이메일에 사용됩니다', es: 'Se usan para consultas de clientes y correos de confirmación', vi: 'Dùng cho khách liên hệ và email xác nhận lịch hẹn' },
