  'settings.stSlot30': { 'zh-Hans': '30 分钟 (推荐标准)', en: '30 minutes (recommended)', ko: '30분 (권장 표준)', es: '30 minutos (recomendado)', vi: '30 phút (khuyến nghị)' },
  'settings.stSlot60': { 'zh-Hans': '60 分钟 (整点模式)', en: '60 minutes (on the hour)', ko: '60분 (정시 모드)', es: '60 minutos (en punto)', vi: '60 phút (theo giờ chẵn)' },
  'settings.stDepositTitle': { 'zh-Hans': '预约押金与信用卡担保政策', en: 'Deposit and card-guarantee policy', ko: '예약 보증금 및 카드 보증 정책', es: 'Política de depósito y garantía con tarjeta', vi: 'Chính sách đặt cọc và bảo lãnh thẻ' },
  'settings.stDepositDesc': { 'zh-Hans': '防止恶意占位与放鸽子 (No-Show)，预约时扣收定金或预授权', en: 'Prevents slot squatting and no-shows by taking a deposit or pre-authorisation at booking time', ko: '자리 선점과 노쇼를 방지하기 위해 예약 시 보증금 또는 사전 승인을 받습니다', es: 'Evita reservas fantasma y no-shows cobrando un depósito o una preautorización al reservar', vi: 'Ngăn giữ chỗ ảo và bỏ hẹn (No-Show) bằng cách thu cọc hoặc tạm giữ tiền khi đặt lịch' },
