  'settings.stFallbackPhone': { 'zh-Hans': '人工转接号码 (Fallback Forward Phone)', en: 'Human fallback forwarding number', ko: '상담원 전환 번호 (Fallback Forward Phone)', es: 'Número de desvío a un agente (Fallback Forward Phone)', vi: 'Số chuyển máy cho người thật (Fallback Forward Phone)' },
  'settings.stFallbackPhoneDesc': { 'zh-Hans': '当客户要求人工协助、出现疑难问题或网络出现波动时，系统自动呼转至此手机号', en: 'When the caller asks for a person, hits a difficult case, or the network is unstable, the system forwards the call to this number automatically', ko: '고객이 상담원을 요청하거나 난이도가 높은 문의, 네트워크 불안정이 발생하면 시스템이 이 번호로 자동 전환합니다', es: 'Cuando el cliente pide hablar con una persona, surge un caso complejo o la red falla, el sistema desvía la llamada a este número', vi: 'Khi khách yêu cầu gặp người thật, gặp tình huống khó hoặc mạng chập chờn, hệ thống sẽ tự chuyển tới số này' },
  'settings.stVoiceStyle': { 'zh-Hans': '语音助手语调风格', en: 'Voice assistant tone', ko: '음성 도우미 어조 스타일', es: 'Tono del asistente de voz', vi: 'Phong cách giọng trợ lý' },
  'settings.stVoiceStyleDesc': { 'zh-Hans': '选择适合您门店品牌调性的 AI 语音语速与情感色彩', en: 'Choose the AI speaking pace and emotional colour that fits your brand', ko: '매장 브랜드 톤에 맞는 AI 음성 속도와 감정 색채를 선택하세요', es: 'Elige el ritmo y el tono emocional de la IA que encajen con tu marca', vi: 'Chọn tốc độ nói và sắc thái cảm xúc của AI phù hợp với thương hiệu' },
  'settings.stVoiceWarm': { 'zh-Hans': '温和热情 (Spa/养生推荐)', en: 'Warm and welcoming (recommended for spa and wellness)', ko: '따뜻하고 친근함 (스파·웰니스 권장)', es: 'Cálido y acogedor (recomendado para spa y bienestar)', vi: 'Ấm áp thân thiện (khuyến nghị cho spa / dưỡng sinh)' },
