  'settings.stVoiceEfficient': { 'zh-Hans': '简练高效 (快剪美甲)', en: 'Concise and efficient (quick cuts and nails)', ko: '간결하고 효율적 (퀵컷·네일)', es: 'Conciso y eficiente (cortes rápidos y uñas)', vi: 'Ngắn gọn hiệu quả (cắt nhanh / làm nail)' },
  'settings.stAutoBook': { 'zh-Hans': '意图达成后自动建单 (Auto Book)', en: 'Create the booking automatically once intent is clear (auto book)', ko: '의도 확정 시 자동 예약 생성 (Auto Book)', es: 'Crear la reserva automáticamente al detectar la intención (Auto Book)', vi: 'Tự tạo lịch khi xác định rõ ý định (Auto Book)' },
  'settings.stAutoBookDesc': { 'zh-Hans': '开启后通话达成明确预约意图直接写入系统日程；关闭则生成待审核的意图草案', en: 'When enabled, a clear booking intent is written straight into the schedule; when disabled, a draft is created for review', ko: '활성화하면 통화에서 명확한 예약 의도가 확인될 때 일정에 바로 기록되고, 비활성화하면 검토 대기 초안이 생성됩니다', es: 'Si se activa, la intención clara de reserva se escribe directamente en la agenda; si no, se crea un borrador para revisar', vi: 'Khi bật, ý định đặt lịch rõ ràng sẽ ghi thẳng vào lịch; khi tắt, hệ thống tạo bản nháp chờ duyệt' },
  'settings.stPublicMainNumber': { 'zh-Hans': '门店对外公示主号', en: 'Public main number', ko: '대외 공시 대표 번호', es: 'Número principal público', vi: 'Số điện thoại công bố chính' },
