  'settings.stConsentTitle': { 'zh-Hans': '知情同意与免责声明标题', en: 'Consent and liability waiver title', ko: '동의 및 면책 선언 제목', es: 'Título del consentimiento y la exención', vi: 'Tiêu đề bản đồng ý và miễn trừ trách nhiệm' },
  'settings.stConsentBody': { 'zh-Hans': '免责声明与告知书正文', en: 'Waiver and disclosure text', ko: '면책 선언 및 고지 본문', es: 'Texto de la exención y la información', vi: 'Nội dung miễn trừ và thông báo' },
  'settings.stConsentBodyDesc': { 'zh-Hans': '展示在大堂 iPad 签到界面供顾客阅读与电子签名确认', en: 'Displayed on the lobby iPad check-in screen for the guest to read and sign electronically', ko: '로비 iPad 체크인 화면에 표시되어 고객이 읽고 전자 서명하도록 합니다', es: 'Se muestra en la pantalla de registro del iPad para que el cliente lo lea y firme', vi: 'Hiển thị trên màn hình check-in iPad ở sảnh để khách đọc và ký điện tử' },
  'settings.stRequiredFields': { 'zh-Hans': '必填项与偏好采集', en: 'Required fields and data collection', ko: '필수 항목 및 선호 수집', es: 'Campos obligatorios y datos recopilados', vi: 'Trường bắt buộc và dữ liệu thu thập' },
