  'settings.stIssueNewToken': { 'zh-Hans': '签发新设备访问令牌', en: 'Issue a new device access token', ko: '새 기기 접근 토큰 발급', es: 'Emitir un nuevo token de acceso', vi: 'Cấp mã truy cập thiết bị mới' },
  'settings.stIssueTokenDesc': { 'zh-Hans': '在 iPad 终端 App 启动时输入生成的专用令牌即可自动绑定本店并激活副屏模式。', en: 'Enter the generated token when the iPad app starts to bind it to this store and activate display mode.', ko: 'iPad 단말 앱 실행 시 생성된 전용 토큰을 입력하면 자동으로 이 매장에 연결되고 디스플레이 모드가 활성화됩니다.', es: 'Introduce el token generado al iniciar la app del iPad para vincularlo a este local y activar el modo pantalla.', vi: 'Khi khởi động ứng dụng trên iPad, nhập mã đã tạo để tự động liên kết cửa hàng và bật chế độ màn hình phụ.' },
  'settings.stTokenReady': { 'zh-Hans': '· 令牌已就绪', en: '· token ready', ko: '· 토큰 준비 완료', es: '· token listo', vi: '· mã đã sẵn sàng' },
  'settings.stTokenEnterHint': { 'zh-Hans': '请在目标设备端完成输入。该令牌具有大堂签到与副屏同步权限。', en: 'Enter it on the target device. This token grants lobby check-in and customer-display sync permissions.', ko: '대상 기기에서 입력을 완료해 주세요. 이 토큰은 로비 체크인과 디스플레이 동기화 권한을 가집니다.', es: 'Introdúcelo en el dispositivo de destino. Este token otorga permisos de registro en el vestíbulo y de sincronización de la pantalla.', vi: 'Vui lòng nhập trên thiết bị đích. Mã này có quyền check-in ở sảnh và đồng bộ màn hình phụ.' },
  'settings.stConsentTemplateTitle': { 'zh-Hans': '大堂 iPad 客户健康问卷与免责知情书模板', en: 'Lobby iPad health questionnaire and consent template', ko: '로비 iPad 고객 건강 문진표 및 면책 동의서 템플릿', es: 'Plantilla del cuestionario de salud y consentimiento del iPad', vi: 'Mẫu phiếu khai báo sức khỏe và bản đồng ý trên iPad sảnh' },
  'settings.stRequireSignature': { 'zh-Hans': '强制要求顾客正楷电子签名 (Digital Signature Required)', en: 'Require a handwritten electronic signature', ko: '고객 정자 전자 서명 필수 (Digital Signature Required)', es: 'Exigir firma electrónica manuscrita (Digital Signature Required)', vi: 'Bắt buộc chữ ký điện tử viết tay (Digital Signature Required)' },
  'settings.stCollectAllergies': { 'zh-Hans': '采集精油/产品过敏史与身体重点避开部位', en: 'Collect essential-oil and product allergy history plus areas to avoid', ko: '에센셜 오일·제품 알레르기 이력과 회피 부위 수집', es: 'Recopilar alergias a aceites y productos y zonas a evitar', vi: 'Thu thập tiền sử dị ứng tinh dầu / sản phẩm và vùng cần tránh' },
  'settings.stCollectPressure': { 'zh-Hans': '采集受力偏好 (Light 较轻 / Medium 适中 / Strong 较重)', en: 'Collect pressure preference (light / medium / strong)', ko: '압박 선호 수집 (Light 약함 / Medium 보통 / Strong 강함)', es: 'Recopilar la preferencia de presión (Light / Medium / Strong)', vi: 'Thu thập mức lực mong muốn (Light nhẹ / Medium vừa / Strong mạnh)' },
  'settings.stApiTitle': { 'zh-Hans': '公开 API 与官网插件对接 (CORS & Webhooks)', en: 'Public API and website plugin integration (CORS and webhooks)', ko: '공개 API 및 웹사이트 플러그인 연동 (CORS & Webhooks)', es: 'API pública e integración con plugins web (CORS y webhooks)', vi: 'API công khai và tích hợp plugin website (CORS & Webhooks)' },
  'settings.stApiDesc': { 'zh-Hans': '配置网站域名白名单、获取公开 API Key 以供官网前端或第三方插件调用在线预约能力', en: 'Manage the website domain allowlist and obtain the public API key so your site or third-party plugins can use online booking', ko: '웹사이트 도메인 허용 목록을 설정하고 공개 API Key를 발급받아 자사 웹 프런트나 서드파티 플러그인에서 온라인 예약 기능을 호출할 수 있습니다', es: 'Gestiona la lista blanca de dominios y obtén la clave pública para que tu web o plugins de terceros usen la reserva en línea', vi: 'Cấu hình danh sách tên miền được phép và lấy API Key công khai để website hoặc plugin bên thứ ba gọi chức năng đặt lịch' },
