  'settings.stPublicKey': { 'zh-Hans': '公开 API 访问密钥 (Public Key)', en: 'Public API access key', ko: '공개 API 접근 키 (Public Key)', es: 'Clave pública de acceso a la API (Public Key)', vi: 'Khóa truy cập API công khai (Public Key)' },
  'settings.stCorsOrigins': { 'zh-Hans': '允许调用预约 API 的网站域名 (CORS Allowed Origins)', en: 'Website domains allowed to call the booking API (CORS allowed origins)', ko: '예약 API 호출을 허용할 도메인 (CORS Allowed Origins)', es: 'Dominios autorizados a llamar a la API de reservas (CORS Allowed Origins)', vi: 'Tên miền được phép gọi API đặt lịch (CORS Allowed Origins)' },
  'settings.stCorsDesc': { 'zh-Hans': '仅以下域名的前端网页有权调用您的预约接口，防范跨域非法仿冒。', en: 'Only front-end pages on the domains below may call your booking endpoints, preventing cross-origin impersonation.', ko: '아래 도메인의 프런트엔드 페이지만 예약 API를 호출할 수 있어 교차 출처 위조를 방지합니다.', es: 'Solo las páginas de estos dominios pueden llamar a tus endpoints de reserva, lo que evita suplantaciones entre orígenes.', vi: 'Chỉ trang web thuộc các tên miền dưới đây được gọi API đặt lịch của bạn, ngăn giả mạo từ nguồn khác.' },
